// Full Games Catalog matching existing games const baseCatalog = [ { id: "eaglercraft-skyfactory", title: "Minecraft (SkyFactory Mod)", category: "Sandbox", description: "Eaglercraft SkyFactory Mod! Survive on a floating island, automate resource gathering, build tech machines, and expand in the sky.", type: "skyfactory", thumbnail: "/minecraft_logo.jpg", rating: 5.0, plays: "1.8M", controls: "WASD Move, Mouse Look &amp; Mine/Place, Space Jump, Shift Sneak, E Inventory", featured: true, popular: true, isGnMath: false }, { id: "minecraft-tuff", title: "Minecraft (Tuff Client)", category: "Sandbox", description: "Full Minecraft WASM offline client featuring high FPS gameplay, multiplayer, custom skins, and singleplayer survival.", type: "minecraft", thumbnail: "/minecraft_logo.jpg", rating: 5.0, plays: "2.5M", controls: "WASD Move, Mouse Look &amp; Mine/Place, Space Jump, Shift Sneak, E Inventory", featured: true, popular: true, isGnMath: false }, { id: "ev-io", title: "ev.io", category: "Action", description: "Futuristic 3D FPS arena shooter! Master double jumps, teleportation, grenades, and railguns in multiplayer combat.", type: "url", url: "https://ev.io/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.9, plays: "1.1M", controls: "WASD Move, Mouse Aim &amp; Shoot, Space Double Jump, Shift Teleport", featured: true, popular: true, isGnMath: true }, { id: "geometry-dash", title: "Geometry Dash Lite", category: "Arcade", description: "Jump, fly, and flip your way through dangerous geometric passages in this rhythm platformer!", type: "url", url: "https://geometrydashlite.io/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.9, plays: "1.4M", controls: "Spacebar / Up Arrow to Jump", featured: true, popular: true, isGnMath: true }, { id: "subway-surfers", title: "Subway Surfers", category: "Arcade", description: "Dash as fast as you can through subway tracks! Dodge oncoming trains and leap over barriers.", type: "url", url: "https://subwaysurfersgame.io/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.9, plays: "1.8M", controls: "Left / Right Arrows Switch Lanes, Up Jump, Down Roll", featured: true, popular: true, isGnMath: true }, { id: "1v1-lol", title: "1v1.LOL RELOADED", category: "Action", description: "3D building and shooting simulator! Fight in 1v1 duels, build ramps and walls in 1v1.LOL RELOADED.", type: "url", url: "https://1v1lolreloaded.com/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.9, plays: "1.3M", controls: "WASD Move, Mouse Shoot / Build", featured: true, popular: true, isGnMath: true }, { id: "drive-mad", title: "Drive Mad", category: "Racing", description: "Drive a monster truck over crazy physics-based obstacle tracks without flipping!", type: "url", url: "https://drivemad.org/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.9, plays: "920K", controls: "W / D Drive Forward, S / A Brake &amp; Reverse", featured: true, popular: true, isGnMath: true }, { id: "stickman-hook", title: "Stickman Hook", category: "Skill", description: "Swing like Spider-Man as a bouncy stickman! Grapple onto pegs and soar to the finish line.", type: "url", url: "https://stickmanhookgame.org/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.8, plays: "810K", controls: "Spacebar / Mouse Click Hook &amp; Swing", featured: false, popular: true, isGnMath: true }, { id: "vex-7", title: "Vex 7", category: "Action", description: "Hardcore stickman parkour! Master deadly spikes, laser beams, and wall jumps.", type: "url", url: "https://vex7.io/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.9, plays: "760K", controls: "WASD / Arrow Keys Move &amp; Jump", featured: true, popular: true, isGnMath: true }, { id: "basket-random", title: "Basket Random", category: "Sports", description: "Wacky ragdoll 2-player basketball with random physics and courts!", type: "url", url: "https://basketrandom.org/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.8, plays: "890K", controls: "P1: W Key Jump, P2: Up Arrow Jump", featured: true, popular: true, isGnMath: true }, { id: "soccer-random", title: "Soccer Random", category: "Sports", description: "Hilarious single button ragdoll soccer! Play on random weather fields.", type: "url", url: "https://soccerrandom.org/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.8, plays: "730K", controls: "P1: W Key Kick, P2: Up Arrow Kick", featured: false, popular: true, isGnMath: true }, { id: "half-life-2", title: "Half-Life 2", category: "Action", description: "Play Half-Life 2 directly in your browser! Experience Gordon Freeman's iconic sci-fi FPS journey through City 17 with realistic physics and gravity gun mechanics.", type: "half-life", url: "https://hl2.slqnt.dev/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 5.0, plays: "950K", controls: "WASD Walk, Mouse Aim &amp; Fire, Space Jump, Shift Sprint, E Gravity Gun", featured: true, popular: true }, { id: "half-life-1", title: "Half-Life 1", category: "Action", description: "Play the original 1998 GoldSrc FPS classic in your browser! Survive Black Mesa as Dr. Gordon Freeman.", type: "half-life", url: "https://hl2.slqnt.dev/", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.9, plays: "880K", controls: "WASD Move, Mouse Shoot, Space Jump, E Use", featured: true, popular: true }, { id: "retro-bowl", title: "Retro Bowl", category: "Sports", description: "The ultimate 8-bit American football management game! Call plays, pass, run, and lead your team.", type: "url", url: "https://game316009.konggames.com/gamez/0031/6009/live/index.html", thumbnail: "https://i.ibb.co/JF2kVVLZ/IMG-1638.jpg", rating: 4.9, plays: "1.1M", controls: "Mouse Drag &amp; Release to Pass, W/S Dodge", featured: true, popular: true, isGnMath: true }, { id: "tunnel-rush", title: "Tunnel Rush", category: "Arcade", description: "Blaze through a 3D neon tunnel at lightning speed! Dodge