function checkCleverInput() { const input = document.getElementById('cleverSearchInput'); const lolBanner = document.getElementById('lolrationCleverBanner'); const frozenBanner = document.getElementById('frozenCleverBanner'); const val = input ? input.value.trim().toLowerCase() : '';
