function exportBackupJSON() { const backup = { favorites, customGames, timestamp: new Date().toISOString() }; const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backup, null, 2)); const dlAnchorElem = document.createElement('a'); dlAnchorElem.setAttribute("href", dataStr); dlAnchorElem.setAttribute("download", `tundra_backup_${Date.now()}.json`); dlAnchorElem.click(); }
function importBackupJSON(event) { const file = event.target.files[0]; if (!file) return; const reader = new FileReader(); reader.onload = function(e) { try { const parsed = JSON.parse(e.target.result); if (parsed.favorites &amp;&amp; Array.isArray(parsed.favorites)) { favorites = parsed.favorites; localStorage.setItem('frost_favorites', JSON.stringify(favorites)); } if (parsed.customGames &amp;&amp; Array.isArray(parsed.customGames)) { customGames = parsed.customGames; localStorage.setItem('frost_custom_games', JSON.stringify(customGames)); gamesList = [...baseCatalog, ...customGames]; } renderGames(); alert("Backup restored successfully!"); closeDriveModal(); } catch (err) { alert("Invalid backup file."); } }; reader.readAsText(file); }
