function isAdHost(hostname) { if (!hostname) return false; const h = hostname.toLowerCase(); for (const bad of AD_HOSTS) { if (h === bad || h.endsWith("." + bad)) return true; } return false; }
function errorPage(title, message, status = 502) { const html = `<html><head><meta charset="utf-8" /><title>${title}</title>
</head><body><div class="box"><h1>${title}</h1><p>${message}</p></div></body></html>`; return new Response(html, { status: 200, headers: { "content-type": "text/html; charset=utf-8", "access-control-allow-origin": "*", "x-proxy-status": String(status) }, }); }
function proxied(target) { return `${PROXY_PATH}?url=${encodeURIComponent(target)}`; }
function resolveUrl(base, ref) { if (!ref) return null; const trimmed = ref.trim(); if (!trimmed) return null; if (/^(data:|blob:|javascript:|mailto:|tel:|#)/i.test(trimmed)) return null; try { return new URL(trimmed, base).toString(); } catch { return null; } }
function rewriteAttr(html, attr, base) { const re = new RegExp(`(\\s${attr}\\s*=\\s*)(["'])([\\s\\S]*?)\\2`, "gi"); return html.replace(re, (_m, pre, q, val) => { if (val.includes('/api/proxy?url=')) return `${pre}${q}${val}${q}`; const abs = resolveUrl(base, val); if (!abs) return `${pre}${q}${val}${q}`; return `${pre}${q}${proxied(abs)}${q}`; }); }
function rewriteSrcset(html, base) { return html.replace(/(\ssrcset\s*=\s*)(["'])([\s\S]*?)\2/gi, (_m, pre, q, val) => { const parts = val.split(",").map((p) => { const seg = p.trim().split(/\s+/); if (seg[0] &amp;&amp; seg[0].includes('/api/proxy?url=')) return p; const abs = resolveUrl(base, seg[0]); if (!abs) return p; seg[0] = proxied(abs); return seg.join(" "); }); return `${pre}${q}${parts.join(", ")}${q}`; }); }
function rewriteCss(css, base) { css = css.replace(/url\(\s*(['"]?)([^'")]+)\1\s*\)/gi, (_m, q, val) => { if (val.includes('/api/proxy?url=')) return `url(${q}${val}${q})`; const abs = resolveUrl(base, val); if (!abs) return `url(${q}${val}${q})`; return `url(${q}${proxied(abs)}${q})`; }); css = css.replace(/@import\s+(['"])([^'"]+)\1/gi, (_m, q, val) => { const abs = resolveUrl(base, val); if (!abs) return `@import ${q}${val}${q}`; return `@import ${q}${proxied(abs)}${q}`; }); return css; }
function rewriteHtml(html, base) { html = html.replace(/<meta[^>]+http-equiv=["']?content-security-policy["']?[^>]*>/gi, ""); html = html.replace(/<meta[^>]+http-equiv=["']?x-frame-options["']?[^>]*>/gi, "");
html = html.replace(/(<style[^>]*>)([\s\S]*?)(<\/style>)/gi, (_m, open, css, close) => { return open + rewriteCss(css, base) + close; });
for (const attr of ["href", "src", "action", "poster", "data-src", "data-href"]) { html = rewriteAttr(html, attr, base); } html = rewriteSrcset(html, base);
const injection = ` <base href="${proxied(base)}"> <script>(function(){ var PROXY = ${JSON.stringify(PROXY_PATH)}; var BASE = ${JSON.stringify(base)}; function abs(u){ try { return new URL(u, BASE).toString(); } catch(e){ return null; } } function wrap(u){ if(!u||typeof u!=='string') return u; if(u.indexOf(PROXY+'?')===0 || u.includes(PROXY+'?url=')) return u; if(/^(data:|blob:|javascript:|mailto:|tel:|#)/i.test(u)) return u; var a = abs(u); return a ? PROXY+'?url='+encodeURIComponent(a) : u; } var _fetch = window.fetch; window.fetch = function(input, init){ try { if(typeof input==='string'){ input = wrap(input); } else if(input &amp;&amp; input.url){ input = new Request(wrap(input.url), input); } } catch(e){} return _fetch.call(this, input, init); }; var _open = XMLHttpRequest.prototype.open; XMLHttpRequest.prototype.open = function(m,u){ try { arguments[1] = wrap(u); } catch(e){} return _open.apply(this, arguments); }; document.addEventListener('submit', function(e){ var f = e.target; if(!f || !f.action) return; try { f.action = wrap(f.action); } catch(e){} }, true); document.addEventListener('click', function(e){ var a = e.target &amp;&amp; e.target.closest ? e.target.closest('a[href]') : null; if(!a) return; if(a.target==='_blank') return; var href = a.getAttribute('href'); if(!href) return; if(/^(javascript:|mailto:|tel:|#)/i.test(href)) return; e.preventDefault(); window.location.href = wrap(href); }, true); })();<\/script> `; if (/<head[^>]*>/i.test(html)) { html = html.replace(/<head([^>]*)>/i, (m) => m + injection); } else { html = injection + html; } return html; }
async function handleProxy(request) { const url = new URL(request.url); const target = url.searchParams.get("url"); if (!target) return errorPage("Missing URL", "No target URL was provided to the proxy.", 400);
let targetUrl; try { targetUrl = new URL(target); } catch { try { targetUrl = new URL(/^https?:\/\//i.test(target) ? target : `https://${target}`); } catch { return errorPage("Invalid URL", "The URL you entered could not be parsed.", 400); } } if (!/^https?:$/.test(targetUrl.protocol)) { return errorPage("Blocked scheme", "Only http and https URLs are allowed.", 400); }
if (isAdHost(targetUrl.hostname)) { return new Response(null, { status: 204, headers: { "access-control-allow-origin": "*", "x-proxy-adblock": "1" } }); }
const fwdHeaders = { "user-agent": request.headers.get("user-agent") || "Mozilla/5.0 (compatible; TundraProxy/1.0)", accept: request.headers.get("accept") || "*/*", "accept-language": request.headers.get("accept-language") || "en-US,en;q=0.9", }; const range = request.headers.get("range"); if (range) fwdHeaders["range"] = range;
let body; if (request.method !== "GET" &amp;&amp; request.method !== "HEAD") { body = await request.arrayBuffer(); const ct = request.headers.get("content-type"); if (ct) fwdHeaders["content-type"] = ct; }
let upstream; try { upstream = await fetch(targetUrl.toString(), { method: request.method, headers: fwdHeaders, body, redirect: "manual", }); } catch (e) { return errorPage("Site unreachable", `Could not load <b>${targetUrl.hostname}</b>. It may be down, unresolvable, or blocking proxies.<br /><br /><small>${e.message}</small>`, 502); }
if (upstream.status >= 300 &amp;&amp; upstream.status < 400) { const loc = upstream.headers.get("location"); if (loc) { const abs = resolveUrl(targetUrl.toString(), loc); if (abs) { return new Response(null, { status: upstream.status, headers: { location: proxied(abs) }, }); } } }
const contentType = (upstream.headers.get("content-type") || "").toLowerCase(); const outHeaders = new Headers(); outHeaders.set("access-control-allow-origin", "*"); const stripped = new Set([ "content-security-policy", "content-security-policy-report-only", "x-frame-options", "frame-options", "cross-origin-opener-policy", "cross-origin-embedder-policy", "cross-origin-resource-policy", "strict-transport-security", "content-length", "content-encoding", "transfer-encoding", ]); for (const [k, v] of upstream.headers.entries()) { if (stripped.has(k.toLowerCase())) continue; outHeaders.set(k, v); }
if (contentType.includes("text/html")) { const text = await upstream.text(); const rewritten = rewriteHtml(text, targetUrl.toString()); outHeaders.set("content-type", "text/html; charset=utf-8"); return new Response(rewritten, { status: upstream.status, headers: outHeaders }); } if (contentType.includes("text/css")) { const text = await upstream.text(); const rewritten = rewriteCss(text, targetUrl.toString()); outHeaders.set("content-type", "text/css; charset=utf-8"); return new Response(rewritten, { status: upstream.status, headers: outHeaders }); }
return new Response(upstream.body, { status: upstream.status, headers: outHeaders }); }
// Proxy Functions function handleProxyNavHome(e) { e.preventDefault(); const input = document.getElementById('proxyUrlInputHome').value.trim(); executeProxySearch(input); }
function handleProxyNav(e) { e.preventDefault(); const input = document.getElementById('proxyUrlInput').value.trim(); executeProxySearch(input); }
function executeProxySearch(input) { if (!input) return;
let url = input; if (!/^https?:\/\//i.test(url)) { if (url.includes('.') &amp;&amp; !url.includes(' ')) { url = 'https://' + url; } else { const backend = localStorage.getItem('proxyBackend') || 'xenorio'; updateProxyBackendUI(backend); const engine = localStorage.getItem('proxySearchEngine') || 'bing'; if (engine === 'ecosia') url = 'https://www.ecosia.org/search?q=' + encodeURIComponent(input); else if (engine === 'brave') url = 'https://search.brave.com/search?q=' + encodeURIComponent(input); else if (engine === 'ddg') url = 'https://lite.duckduckgo.com/lite/?q=' + encodeURIComponent(input); else url = 'https://www.bing.com/search?q=' + encodeURIComponent(input); } }
document.getElementById('proxyUrlInput').value = url; if (document.getElementById('proxyUrlInputHome')) { document.getElementById('proxyUrlInputHome').value = url; } const backend = localStorage.getItem('proxyBackend') || 'xenorio'; let proxyEndpoint = './api/proxy?url=' + encodeURIComponent(url); if (backend === 'xenorio') { proxyEndpoint = 'https://find.xenorio.xyz/'; }
const welcome = document.getElementById('proxyWelcome'); const iframe = document.getElementById('proxyIframe'); if (welcome) welcome.classList.add('hidden'); if (iframe) { iframe.classList.remove('hidden'); iframe.src = proxyEndpoint; } }
function toggleProxyFullscreen() { const container = document.getElementById('proxyFrameContainer'); const isFullscreen = container.classList.contains('fixed'); const iconEnter = document.getElementById('iconEnterFs'); const iconExit = document.getElementById('iconExitFs'); const textFs = document.getElementById('textFs');
if (isFullscreen) { container.classList.remove('fixed', 'inset-0', 'z-[9999]'); iconEnter.classList.remove('hidden'); iconExit.classList.add('hidden'); textFs.innerText = 'Full Screen'; } else { container.classList.add('fixed', 'inset-0', 'z-[9999]'); iconEnter.classList.add('hidden'); iconExit.classList.remove('hidden'); textFs.innerText = 'Exit Full Screen'; } }
function handleProxySubmit(e) { e.preventDefault(); const input = document.getElementById('proxyAddress').value.trim(); if (!input) return;
let url = input; if (!/^https?:\/\//i.test(url)) { if (url.includes('.') &amp;&amp; !url.includes(' ')) { url = 'https://' + url; } else { const engine = document.getElementById('proxyEngine').value; if (engine === 'duckduckgo') url = 'https://duckduckgo.com/?q=' + encodeURIComponent(input); else if (engine === 'bing') url = 'https://www.bing.com/search?q=' + encodeURIComponent(input); else if (engine === 'brave') url = 'https://search.brave.com/search?q=' + encodeURIComponent(input); else url = 'https://www.bing.com/search?q=' + encodeURIComponent(input); } } navigateProxy(url); }
function navigateProxy(url) { document.getElementById('proxyUrlDisplay').innerText = url; const proxyEndpoint = './api/proxy?url=' + encodeURIComponent(url); document.getElementById('proxyIframe').src = proxyEndpoint; document.getElementById('proxyFrameContainer').classList.remove('hidden'); document.getElementById('proxyFrameContainer').classList.add('flex'); document.getElementById('proxyShortcuts').classList.add('hidden'); }
function closeProxyFrame() { document.getElementById('proxyIframe').src = 'about:blank'; document.getElementById('proxyFrameContainer').classList.add('hidden'); document.getElementById('proxyFrameContainer').classList.remove('flex'); document.getElementById('proxyShortcuts').classList.remove('hidden'); }
// Panic Mode &amp; Believable Classroom Subject Templates const panicSubjects = { math: { id: "math", name: "Math", icon: "📐", fileName: "Calculus_Unit_4_Optimization_and_Derivatives_HW.docx", tag: "AP Calculus BC • Assignment 4.2", title: "Unit 4: Optimization, Concavity &amp; Second Derivative Tests", department: "Department of Mathematics | Advanced Placement Calculus | Fall 2026", content: ` <h3 class="text-lg font-semibold text-slate-800 mt-2">1. Concavity and Critical Point Analysis</h3> <p>For the continuous differentiable function <em>f(x) = 2x³ - 9x² + 12x - 4</em>, determine all critical points, intervals of increase/decrease, and points of inflection.</p> <div class="bg-slate-50 border border-slate-200 p-4 rounded-lg my-3 font-mono text-xs text-slate-700 leading-relaxed"> Step 1: First Derivative<br/> f'(x) = 6x² - 18x + 12 = 6(x - 1)(x - 2) = 0 ⇒ Critical Points at x = 1 and x = 2<br/><br/> Step 2: Second Derivative Test<br/> f''(x) = 12x - 18<br/> • f''(1) = -6 &lt; 0 ⇒ Local Maximum at (1, 1)<br/> • f''(2) = +6 &gt; 0 ⇒ Local Minimum at (2, 0)<br/> • f''(x) = 0 ⇒ x = 1.5 (Inflection Point at (1.5, 0.5)) </div> <h3 class="text-lg font-semibold text-slate-800 mt-4">2. Applied Optimization Problem</h3> <p>A rectangular field is to be enclosed using 200 meters of fencing material. One side borders a straight river bank and requires no fencing. Find the maximum area of the field.</p> <div class="bg-blue-50/60 border-l-4 border-blue-500 p-3.5 rounded my-3 text-xs text-slate-700"> <strong>Solution Formula:</strong> Let width = <em>x</em>, length = <em>y</em>. Constraint equation: 2<em>x</em> + <em>y</em> = 200 ⇒ <em>y</em> = 200 - 2<em>x</em>. Area function <em>A(x)</em> = <em>x</em>(200 - 2<em>x</em>) = 200<em>x</em> - 2<em>x</em>². Derivative <em>A'(x)</em> = 200 - 4<em>x</em> = 0 ⇒ <em>x</em> = 50m, <em>y</em> = 100m. Maximum Area = <strong>5,000 m²</strong>. </div> <h3 class="text-lg font-semibold text-slate-800 mt-4">3. Practice Exercises</h3> <ol class="list-decimal list-inside space-y-1.5 text-xs text-slate-700"> <li>Evaluate ∫ sin²(x) cos(x) dx from 0 to π/2 using <em>u</em>-substitution.</li> <li>Find the volume of the solid generated by revolving y = √x about the x-axis from x = 0 to x = 4.</li> <li>State the Mean Value Theorem for derivatives and verify for g(x) = x² - 4x on [1, 4].</li> </ol> ` }, tech: { id: "tech", name: "Tech / CS", icon: "💻", fileName: "CS102_Data_Structures_Array_Tree_Lab.docx", tag: "Computer Science 102 • Lab Module 3", title: "Unit 3: Binary Search Trees &amp; Big-O Time Complexity Analysis", department: "Department of Computer Science &amp; Information Tech | Lab Draft", content: ` <h3 class="text-lg font-semibold text-slate-800 mt-2">1. Asymptotic Complexity Overview</h3> <p>Comparison of common algorithmic time complexities for linear data structures versus balanced tree graphs.</p> <div class="overflow-x-auto my-3"> <table class="w-full text-left text-xs border-collapse border border-slate-200"> <thead class="bg-slate-100 font-semibold text-slate-800 border-b border-slate-200"> <tr> <th class="p-2 border border-slate-200">Data Structure</th> <th class="p-2 border border-slate-200">Access (Avg)</th> <th class="p-2 border border-slate-200">Search (Avg)</th> <th class="p-2 border border-slate-200">Insertion (Worst)</th> </tr> </thead> <tbody class="divide-y divide-slate-200 font-mono text-[11px] text-slate-700"> <tr><td class="p-2 border border-slate-200 font-sans">Array / Vector</td><td class="p-2 border border-slate-200">O(1)</td><td class="p-2 border border-slate-200">O(N)</td><td class="p-2 border border-slate-200">O(N)</td></tr> <tr><td class="p-2 border border-slate-200 font-sans">Singly Linked List</td><td class="p-2 border border-slate-200">O(N)</td><td class="p-2 border border-slate-200">O(N)</td><td class="p-2 border border-slate-200">O(1)</td></tr> <tr><td class="p-2 border border-slate-200 font-sans">Binary Search Tree</td><td class="p-2 border border-slate-200">O(log N)</td><td class="p-2 border border-slate-200">O(log N)</td><td class="p-2 border border-slate-200">O(N)</td></tr> </tbody> </table> </div> <h3 class="text-lg font-semibold text-slate-800 mt-4">2. Node Insertion Implementation (Python)</h3> <div class="bg-slate-900 text-emerald-400 p-4 rounded-lg font-mono text-xs my-3 overflow-x-auto"> class TreeNode:<br/> &#160;&#160;&#160;&#160;def __init__(self, val=0, left=None, right=None):<br/> &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;self.val = val<br/> &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;self.left = left<br/> &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;self.right = right<br/><br/> def insertIntoBST(root: TreeNode, val: int) -&gt; TreeNode:<br/> &#160;&#160;&#160;&#160;if not root: return TreeNode(val)<br/> &#160;&#160;&#160;&#160;if val &lt; root.val:<br/> &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;root.left = insertIntoBST(root.left, val)<br/> &#160;&#160;&#160;&#160;else:<br/> &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;root.right = insertIntoBST(root.right, val)<br/> &#160;&#160;&#160;&#160;return root </div> <div class="bg-emerald-50 border-l-4 border-emerald-500 p-3 rounded text-xs text-slate-700"> <strong>Lab Assignment Task:</strong> Modify the traversal function to perform an in-order depth-first traversal (DFS) that outputs sorted values into an array. </div> ` }, ela: { id: "ela", name: "ELA", icon: "📖", fileName: "ELA_11_Rhetorical_Analysis_Essay_Draft.docx", tag: "English Language Arts 11 • Draft 2", title: "Symbolism, Tone and Moral Growth in Boreal Literature", department: "Department of Humanities &amp; English Language Arts | Essay Assignment", content: ` <div class="border-b border-slate-200 pb-3 mb-3 text-xs text-slate-600 font-mono"> Student: Alex Turner &#8226; Instructor: Dr. Harrison &#8226; Course: ELA 11 Honors &#8226; Date: October 14, 2026 </div> <h3 class="text-lg font-semibold text-slate-800 mt-2">1. Thesis Statement</h3> <p class="text-xs text-slate-700 italic bg-amber-50 p-3 border-l-4 border-amber-400 rounded"> "Through persistent motifs of harsh frost and isolated wilderness, the narrative serves as an allegory for internal psychological endurance, contrasting individual resilience against unyielding environmental barriers." </p> <h3 class="text-lg font-semibold text-slate-800 mt-4">2. Textual Evidence &amp; Critical Commentary</h3> <p> In Chapter 3, the protagonist's journey through the frozen pass mirrors their emotional arc. The author utilizes vivid sensory imagery—describing the "crystalline silence" and "relentless north gale"—to underscore the character's alienation from societal structure. </p> <blockquote class="border-l-2 border-slate-300 pl-4 py-1 my-3 text-xs text-slate-600 italic"> "The ice was not merely a physical obstacle; it was a mirror reflecting the unyielding truth of his own resolve." (Page 84, Line 12) </blockquote> <p> This thematic choice reinforces the romanticist tradition, where nature acts as both antagonist and spiritual catalyst. The shift in tone from ominous despair to quiet acceptance is catalyzed by the appearance of sunrise over the glacier peak. </p> <div class="bg-slate-50 border border-slate-200 p-3 rounded text-xs text-slate-600 mt-4"> <strong>Peer Review Comments:</strong> Strong analytical depth. Ensure proper MLA citation format in Section 3 and expand on the metaphor of the lantern in paragraph 4. </div> ` }, science: { id: "science", name: "Science", icon: "🔬", fileName: "AP_Chemistry_Lab_Reaction_Kinetics.docx", tag: "AP Chemistry • Lab Report 5", title: "Lab Report: Chemical Reaction Rates &amp; Temperature Coefficients", department: "Department of Chemistry &amp; Physical Sciences | Laboratory Report", content: ` <h3 class="text-lg font-semibold text-slate-800 mt-2">1. Experimental Objective &amp; Hypothesis</h3> <p>To determine the rate law and activation energy (<em>E<sub>a</sub></em>) for the reaction between sodium thiosulfate (Na₂S₂O₃) and hydrochloric acid (HCl) across varying thermal conditions.</p> <div class="my-3 bg-slate-100 p-3 rounded text-xs font-mono text-slate-800"> Reaction Equation: Na₂S₂O₃(aq) + 2HCl(aq) → 2NaCl(aq) + SO₂(g) + S(s) + H₂O(l) </div> <h3 class="text-lg font-semibold text-slate-800 mt-4">2. Observed Data &amp; Temperature Measurements</h3> <div class="overflow-x-auto my-3"> <table class="w-full text-left text-xs border-collapse border border-slate-200"> <thead class="bg-slate-100 font-semibold text-slate-800 border-b border-slate-200"> <tr> <th class="p-2 border border-slate-200">Trial #</th> <th class="p-2 border border-slate-200">Temp (°C)</th> <th class="p-2 border border-slate-200">Time to Precipitate (s)</th> <th class="p-2 border border-slate-200">Calculated Rate (1/t)</th> </tr> </thead> <tbody class="divide-y divide-slate-200 text-xs text-slate-700"> <tr><td class="p-2 border border-slate-200">Trial 1</td><td class="p-2 border border-slate-200">20.5 °C</td><td class="p-2 border border-slate-200">48.2 s</td><td class="p-2 border border-slate-200 font-mono">0.0207 s⁻¹</td></tr> <tr><td class="p-2 border border-slate-200">Trial 2</td><td class="p-2 border border-slate-200">30.0 °C</td><td class="p-2 border border-slate-200">24.1 s</td><td class="p-2 border border-slate-200 font-mono">0.0415 s⁻¹</td></tr> <tr><td class="p-2 border border-slate-200">Trial 3</td><td class="p-2 border border-slate-200">40.2 °C</td><td class="p-2 border border-slate-200">11.8 s</td><td class="p-2 border border-slate-200 font-mono">0.0847 s⁻¹</td></tr> </tbody> </table> </div> <div class="bg-sky-50 border-l-4 border-sky-500 p-3 rounded my-3 text-xs text-slate-700"> <strong>Conclusion:</strong> According to the Arrhenius equation <em>k = A e<sup>-E<sub>a</sub> / RT</sup></em>, doubling the absolute temperature increment approximately doubles the reaction rate constant, confirming first-order kinetics with respect to Na₂S₂O₃. </div> ` }, health: { id: "health", name: "Health", icon: "🩺", fileName: "Health_Unit_3_Cardiovascular_Nutrition_Guide.docx", tag: "Health &amp; Wellness Education • Module 3", title: "Unit 3: Human Anatomy, Cardiovascular Systems &amp; Nutrition", department: "Department of Health, Nutrition &amp; Human Development | Study Guide", content: ` <h3 class="text-lg font-semibold text-slate-800 mt-2">1. Cardiovascular System Physiology</h3> <p>The human heart circulates oxygenated blood throughout the systemic loop while returning deoxygenated blood to the pulmonary circuit.</p> <ul class="list-disc list-inside space-y-1.5 text-xs text-slate-700 my-3"> <li><strong>Right Atrium &amp; Ventricle:</strong> Receives systemic venous return via superior/inferior vena cava and pumps blood through pulmonary arteries to the lungs.</li> <li><strong>Left Atrium &amp; Ventricle:</strong> Receives oxygen-enriched blood via pulmonary veins and ejects it under systemic arterial pressure via the aorta.</li> <li><strong>Systolic vs. Diastolic Pressure:</strong> Normal resting baseline average is approximately 120/80 mmHg.</li> </ul> <h3 class="text-lg font-semibold text-slate-800 mt-4">2. Dietary Macronutrient Allocation</h3> <div class="bg-rose-50/60 border-l-4 border-rose-500 p-3.5 rounded my-3 text-xs text-slate-700 space-y-1"> <p><strong>Carbohydrates (4 kcal/g):</strong> Primary metabolic substrate for cerebral and muscle glycogen synthesis.</p> <p><strong>Proteins (4 kcal/g):</strong> Essential amino acid pool for tissue repair, enzymatic synthesis, and immune cellular response.</p> <p><strong>Lipids / Fats (9 kcal/g):</strong> Hormonal regulation, cellular membrane fluidity, and fat-soluble vitamin absorption (A, D, E, K).</p> </div> <h3 class="text-lg font-semibold text-slate-800 mt-4">3. Stress Management &amp; Sleep Hygiene</h3> <p>Maintaining 7–9 hours of continuous slow-wave and REM sleep decreases resting cortisol levels and regulates sympathetic nervous activity.</p> ` }, music: { id: "music", name: "Music", icon: "🎼", fileName: "Music_Theory_Unit_5_Harmonic_Analysis.docx", tag: "Music Theory &amp; Composition • Assignment 5.1", title: "Unit 5: Four-Part Harmony, Cadence Classification &amp; Voice Leading", department: "Department of Music &amp; Performing Arts | Theory Worksheets", content: ` <h3 class="text-lg font-semibold text-slate-800 mt-2">1. Diatonic Chord Progression &amp; Roman Numeral Analysis</h3> <p>Analysis of SATB (Soprano, Alto, Tenor, Bass) four-part chorale writing in C Major (I - IV - V7 - I).</p> <div class="bg-amber-50/80 border border-amber-300 p-4 rounded-lg my-3 font-mono text-xs text-slate-800 space-y-1"> Measure 1: C Major (I) [S: C5, A: G4, T: E4, B: C3]<br/> Measure 2: F Major (IV) [S: C5, A: A4, T: F4, B: F3]<br/> Measure 3: G7 Dominant(V7)[S: B4, A: F4, T: D4, B: G2]<br/> Measure 4: C Major (I) [S: C5, A: E4, T: C4, B: C3] ← Perfect Authentic Cadence (PAC) </div> <h3 class="text-lg font-semibold text-slate-800 mt-4">2. Voice Leading &amp; Counterpoint Rules</h3> <ol class="list-decimal list-inside space-y-1.5 text-xs text-slate-700"> <li><strong>Parallel Motion:</strong> Strictly avoid parallel 5ths and parallel 8ths between any voice pair to maintain independence.</li> <li><strong>Leading Tone Resolution:</strong> Scale degree 7 in a dominant function chord must resolve upwards to the tonic.</li> <li><strong>Voice Crossing:</strong> Keep voices within standard comfortable vocal ranges (Bass: E2–D4, Tenor: C3–G4, Alto: G3–D5, Soprano: C4–G5).</li> </ol> <div class="bg-slate-100 p-3 rounded text-xs text-slate-700 mt-4"> <strong>Assignment Task:</strong> Realize the figured bass line in G Minor for measures 12–16, identifying all deceptive cadences (V - vi). </div> ` }, pe: { id: "pe", name: "PE", icon: "🏃", fileName: "PE_Fitness_Log_Cardio_Endurance_Track.docx", tag: "Physical Education &amp; Fitness • Log 4", title: "Weekly Fitness Log, Target Heart Rate &amp; Aerobic Metrics", department: "Department of Physical Education &amp; Athletics | Weekly Activity Record", content: ` <h3 class="text-lg font-semibold text-slate-800 mt-2">1. Target Heart Rate (THR) Formula (Karvonen Method)</h3> <p>Calculation of optimal training heart rate zone based on resting heart rate (HR<sub>rest</sub> = 65 bpm, Age = 16).</p> <div class="bg-indigo-50 border-l-4 border-indigo-500 p-3.5 rounded my-3 text-xs text-slate-700 font-mono"> HR_max = 220 - 16 = 204 bpm<br/> Heart Rate Reserve (HRR) = 204 - 65 = 139 bpm<br/> Target Zone (60% to 80% Intensity):<br/> • Lower Limit (60%) = (139 × 0.60) + 65 = 148 bpm<br/> • Upper Limit (80%) = (139 × 0.80) + 65 = 176 bpm </div> <h3 class="text-lg font-semibold text-slate-800 mt-4">2. Weekly Activity Tracker Log</h3> <div class="overflow-x-auto my-3"> <table class="w-full text-left text-xs border-collapse border border-slate-200"> <thead class="bg-slate-100 font-semibold text-slate-800 border-b border-slate-200"> <tr> <th class="p-2 border border-slate-200">Day</th> <th class="p-2 border border-slate-200">Activity</th> <th class="p-2 border border-slate-200">Duration</th> <th class="p-2 border border-slate-200">Avg HR</th> <th class="p-2 border border-slate-200">Status</th> </tr> </thead> <tbody class="divide-y divide-slate-200 text-xs text-slate-700"> <tr><td class="p-2 border border-slate-200">Monday</td><td class="p-2 border border-slate-200">PACER Test &amp; Shuttle Runs</td><td class="p-2 border border-slate-200">30 min</td><td class="p-2 border border-slate-200 font-mono">162 bpm</td><td class="p-2 border border-slate-200 text-emerald-600 font-bold">In Zone</td></tr> <tr><td class="p-2 border border-slate-200">Wednesday</td><td class="p-2 border border-slate-200">1-Mile Cardio Endurance Run</td><td class="p-2 border border-slate-200">12 min</td><td class="p-2 border border-slate-200 font-mono">158 bpm</td><td class="p-2 border border-slate-200 text-emerald-600 font-bold">In Zone</td></tr> <tr><td class="p-2 border border-slate-200">Friday</td><td class="p-2 border border-slate-200">Core Flexibility &amp; Static Stretching</td><td class="p-2 border border-slate-200">25 min</td><td class="p-2 border border-slate-200 font-mono">110 bpm</td><td class="p-2 border border-slate-200 text-slate-500">Recovery</td></tr> </tbody> </table> </div> <p class="text-xs text-slate-500 mt-2">Instructor Verification: Verified active completion &amp; HR metrics.</p> ` } };
let currentPanicSubject = localStorage.getItem('frost_panic_subject') || 'math';
function setPanicSubject(subjectKey) { if (!panicSubjects[subjectKey]) subjectKey = 'math'; currentPanicSubject = subjectKey; localStorage.setItem('frost_panic_subject', subjectKey); renderPanicSubject(); }
function renderPanicSubject() { const data = panicSubjects[currentPanicSubject] || panicSubjects.math;
const docIcon = document.getElementById('panicDocIcon'); const docTitle = document.getElementById('panicDocTitle'); const docTag = document.getElementById('panicDocTag'); const mainTitle = document.getElementById('panicMainTitle'); const dept = document.getElementById('panicDepartment'); const body = document.getElementById('panicBody');
if (docIcon) docIcon.innerText = data.icon; if (docTitle) docTitle.innerText = data.fileName; if (docTag) docTag.innerText = data.tag; if (mainTitle) mainTitle.innerText = data.title; if (dept) dept.innerText = data.department; if (body) body.innerHTML = data.content;
// Highlight active subject pill in Settings Modal and Panic Screen Header Object.keys(panicSubjects).forEach(key => { const isSelected = (key === currentPanicSubject);
// Settings modal pill button const modalBtn = document.getElementById(`panicBtn_${key}`); if (modalBtn) { if (isSelected) { modalBtn.className = "px-2.5 py-1 rounded-lg text-xs font-bold transition-all border bg-sky-500 text-slate-950 border-sky-400 shadow-sm cursor-pointer"; } else { modalBtn.className = "px-2.5 py-1 rounded-lg text-xs font-bold transition-all border bg-slate-800 text-slate-300 border-slate-700 hover:bg-slate-700 cursor-pointer"; } }
// Panic screen quick switcher button const screenBtn = document.getElementById(`panicScreenBtn_${key}`); if (screenBtn) { if (isSelected) { screenBtn.className = "px-2.5 py-1 rounded-lg text-xs font-bold transition-all border bg-blue-600 text-white border-blue-500 shadow-sm cursor-pointer"; } else { screenBtn.className = "px-2.5 py-1 rounded-lg text-xs font-bold transition-all border bg-slate-100 text-slate-600 border-slate-300 hover:bg-slate-200 cursor-pointer"; } } }); }
// Panic Mode toggle function togglePanic() { renderPanicSubject(); const panic = document.getElementById('panicScreen'); if (panic) panic.classList.toggle('hidden'); }
window.addEventListener('keydown', (e) => { if (e.key === 'Escape') { togglePanic(); } });
// Realistic Multi-Layer Crystal Snowfall Effect const canvas = document.getElementById('snowCanvas'); const ctx = canvas.getContext('2d'); let flakes = []; let lastFrame = performance.now();
function makeFlake(w, h, seeded) { const kind = Math.random(); const isCrystal = kind < 0.22; const depth = Math.random(); // 0 (far/slow) to 1 (near/fast) const size = isCrystal ? 4 + depth * 8 // 4px to 12px crystal stars : 0.8 + depth * 2.2; // fine flurries return { x: Math.random() * w, y: seeded ? Math.random() * h : -size * 2, size, depth, isCrystal, vy: 0.25 + depth * 1.1 + (isCrystal ? 0.15 : 0), vx: (Math.random() - 0.5) * 0.3, swayAmp: 0.4 + Math.random() * 1.2, swaySpeed: 0.0006 + Math.random() * 0.0016, swayPhase: Math.random() * Math.PI * 2, rot: Math.random() * Math.PI * 2, vr: (Math.random() - 0.5) * 0.01, alpha: isCrystal ? 0.55 + depth * 0.4 : 0.35 + depth * 0.55, arms: 6 }; }
function initSnow() { canvas.width = window.innerWidth; canvas.height = window.innerHeight; const count = Math.min(180, Math.floor(window.innerWidth * window.innerHeight / 14000)); flakes = []; for (let i = 0; i < count; i++) { flakes.push(makeFlake(canvas.width, canvas.height, true)); } }
function drawCrystal(f) { const s = f.size; ctx.save(); ctx.translate(f.x, f.y); ctx.rotate(f.rot); ctx.strokeStyle = `rgba(235, 246, 255, ${f.alpha})`; ctx.lineWidth = Math.max(0.6, s * 0.1); ctx.lineCap = 'round'; ctx.shadowColor = 'rgba(180, 220, 255, 0.6)'; ctx.shadowBlur = s * 0.6; for (let i = 0; i < f.arms; i++) { ctx.rotate((Math.PI * 2) / f.arms); ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(0, -s); ctx.stroke(); // Side crystal branches ctx.beginPath(); ctx.moveTo(0, -s * 0.55); ctx.lineTo(s * 0.28, -s * 0.85); ctx.moveTo(0, -s * 0.55); ctx.lineTo(-s * 0.28, -s * 0.85); ctx.moveTo(0, -s * 0.3); ctx.lineTo(s * 0.18, -s * 0.5); ctx.moveTo(0, -s * 0.3); ctx.lineTo(-s * 0.18, -s * 0.5); ctx.stroke(); } ctx.restore(); }
function drawSnow(now) { if (now === undefined) now = performance.now(); const dt = Math.min(40, now - lastFrame); lastFrame = now;
ctx.clearRect(0, 0, canvas.width, canvas.height);
if (!snowEnabled) { requestAnimationFrame(drawSnow); return; }
for (let f of flakes) { const sway = Math.sin(now * f.swaySpeed + f.swayPhase) * f.swayAmp; f.x += (f.vx + sway * 0.05) * dt * 0.5; f.y += f.vy * dt * 0.5; f.rot += f.vr * dt;
if (f.y - f.size > canvas.height) { f.y = -f.size * 2; f.x = Math.random() * canvas.width; } if (f.x < -20) f.x = canvas.width + 10; if (f.x > canvas.width + 20) f.x = -10;
if (f.isCrystal) { drawCrystal(f); } else { ctx.beginPath(); ctx.fillStyle = `rgba(240, 249, 255, ${f.alpha})`; ctx.shadowColor = 'rgba(200, 230, 255, 0.5)'; ctx.shadowBlur = f.size * 1.5; ctx.arc(f.x, f.y, f.size, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0; } } requestAnimationFrame(drawSnow); }
function toggleSnow() { snowEnabled = !snowEnabled; document.getElementById('snowBtnLabel').innerText = snowEnabled ? 'Snow ON' : 'Snow OFF'; }
window.addEventListener('resize', initSnow); initSnow(); requestAnimationFrame(drawSnow);
// ============ LIGHT BLUE FIRE FLARES (games catalog sides) ============ const flareCanvasL = document.getElementById('flareCanvasLeft'); const flareCanvasR = document.getElementById('flareCanvasRight'); const flareCtxL = flareCanvasL.getContext('2d'); const flareCtxR = flareCanvasR.getContext('2d'); const FLARE_STRIP_W = 120; let flaresL = [], flaresR = []; let lastFlareFrame = performance.now();
function makeFlare(w, h, seeded) { const depth = Math.random(); const size = 0.9 + depth * 2.6; return { x: Math.random() * w, y: seeded ? Math.random() * h : -size * 4, size, depth, vy: 0.35 + depth * 1.4, vx: (Math.random() - 0.5) * 0.25, swayAmp: 0.4 + Math.random() * 1.0, swaySpeed: 0.0005 + Math.random() * 0.0014, swayPhase: Math.random() * Math.PI * 2, life: 0, maxLife: 320 + Math.random() * 420, hue: 198 + Math.random() * 18, // soft cyan -> sky blue alpha: 0.28 + depth * 0.35, tail: 14 + depth * 32 }; }
function sizeFlareCanvas(canvas) { const w = Math.min(FLARE_STRIP_W, Math.floor(window.innerWidth * 0.14)); canvas.width = w; canvas.height = window.innerHeight; canvas.style.width = w + 'px'; return w; }
function initFlares() { const wL = sizeFlareCanvas(flareCanvasL); const wR = sizeFlareCanvas(flareCanvasR); const count = Math.min(55, Math.floor(window.innerHeight / 22)); flaresL = []; flaresR = []; for (let i = 0; i < count; i++) { flaresL.push(makeFlare(wL, window.innerHeight, true)); flaresR.push(makeFlare(wR, window.innerHeight, true)); } }
function drawFlare(ctx, f) { // Soft blue-fire glow — smooth, diffuse, no hard core const r = f.size * 6; const grad = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, r); grad.addColorStop(0, `hsla(${f.hue}, 100%, 88%, ${f.alpha * 0.9})`); grad.addColorStop(0.35, `hsla(${f.hue}, 100%, 70%, ${f.alpha * 0.45})`); grad.addColorStop(0.75, `hsla(${f.hue}, 100%, 55%, ${f.alpha * 0.15})`); grad.addColorStop(1, `hsla(${f.hue}, 100%, 50%, 0)`); ctx.fillStyle = grad; ctx.beginPath(); ctx.arc(f.x, f.y, r, 0, Math.PI * 2); ctx.fill();
// Soft rising wisp — feathered, thin const wispGrad = ctx.createLinearGradient(f.x, f.y - f.tail, f.x, f.y); wispGrad.addColorStop(0, `hsla(${f.hue}, 100%, 80%, 0)`); wispGrad.addColorStop(1, `hsla(${f.hue}, 100%, 88%, ${f.alpha * 0.35})`); ctx.strokeStyle = wispGrad; ctx.lineWidth = Math.max(0.4, f.size * 0.35); ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(f.x, f.y - f.tail); ctx.lineTo(f.x, f.y); ctx.stroke(); }
function stepFlares(ctx, canvas, arr, now, dt) { ctx.clearRect(0, 0, canvas.width, canvas.height); ctx.globalCompositeOperation = 'lighter'; for (let f of arr) { const sway = Math.sin(now * f.swaySpeed + f.swayPhase) * f.swayAmp; f.x += (f.vx + sway * 0.08) * dt * 0.4; f.y += f.vy * dt * 0.35; f.life += dt; if (f.y - f.tail > canvas.height || f.life > f.maxLife) { Object.assign(f, makeFlare(canvas.width, canvas.height, false)); } drawFlare(ctx, f); } ctx.globalCompositeOperation = 'source-over'; }
function animateFlares(now) { if (now === undefined) now = performance.now(); const dt = Math.min(40, now - lastFlareFrame); lastFlareFrame = now; if (!flareCanvasL.classList.contains('hidden')) { stepFlares(flareCtxL, flareCanvasL, flaresL, now, dt); stepFlares(flareCtxR, flareCanvasR, flaresR, now, dt); } requestAnimationFrame(animateFlares); }
window.addEventListener('resize', () => { if (!flareCanvasL.classList.contains('hidden')) initFlares(); }); initFlares(); requestAnimationFrame(animateFlares); // =====================================================================
// Settings Modal &amp; Tools Control Panel function openSettingsModal() { updateSettingsStatus(); const modal = document.getElementById('settingsModal'); if (modal) modal.classList.remove('hidden'); }
