// Tab Cloaking &amp; Masking Engine function setTabTitle(title, faviconUrl) { document.title = title; if (faviconUrl) { let link = document.querySelector("link[rel*='icon']"); if (!link) { link = document.createElement('link'); link.rel = 'shortcut icon'; document.getElementsByTagName('head')[0].appendChild(link); } link.href = faviconUrl; } localStorage.setItem('frost_tab_title', title); if (faviconUrl) localStorage.setItem('frost_tab_favicon', faviconUrl); updateSettingsStatus(); }
