function resetTabTitle() { localStorage.removeItem('frost_tab_title'); localStorage.removeItem('frost_tab_favicon'); document.title = "Google Classroom"; let link = document.querySelector("link[rel*='icon']"); if (link) link.href = "https://ssl.gstatic.com/classroom/favicon.png"; updateSettingsStatus(); }
function updateSettingsStatus() { const badge = document.getElementById('currentCloakBadge'); if (badge) { const titleStr = document.title; badge.innerText = `Active: ${titleStr.length > 22 ? titleStr.substring(0, 20) + '...' : titleStr}`; } const setSnowBtn = document.getElementById('settingsSnowBtn'); if (setSnowBtn) { setSnowBtn.innerText = snowEnabled ? 'Snow ON' : 'Snow OFF'; } }
// about:blank Stealth Tab Launcher function openAboutBlank() { const win = window.open('about:blank', '_blank'); if (!win) { alert("Popup blocked! Please allow popups for this site to open in about:blank."); return; } win.document.title = document.title || 'Google Classroom'; const doc = win.document; const html = document.documentElement.outerHTML; doc.open(); doc.write(html); doc.close(); }
// Link Checking Controller Functions window._linkcheckCurrentMode = 'proxy'; function setLinkcheckMode(mode) { const iframe = document.getElementById('glseriesIframe'); const input = document.getElementById('linkcheckUrlInput'); const statusBadge = document.getElementById('linkcheckStatusBadge'); const modeProxyBtn = document.getElementById('linkcheckBtnProxy'); const modeDirectBtn = document.getElementById('linkcheckBtnDirect'); const directAnchor = document.getElementById('linkcheckDirectAnchor');
let targetUrl = (input ? input.value.trim() : '') || 'https://find.xenorio.xyz/'; if (!/^https?:\/\//i.test(targetUrl)) targetUrl = 'https://' + targetUrl; if (input) input.value = targetUrl; if (directAnchor) directAnchor.href = targetUrl;
let currentMode = mode; if (currentMode === 'current') { currentMode = window._linkcheckCurrentMode || 'proxy'; } window._linkcheckCurrentMode = currentMode;
if (currentMode === 'proxy') { if (iframe) iframe.src = './api/proxy?url=' + encodeURIComponent(targetUrl); if (statusBadge) statusBadge.innerHTML = '<span class="inline-block w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span> Mode: Proxy Stream (Unblocked)'; if (modeProxyBtn) modeProxyBtn.className = "px-3 py-1.5 text-xs font-bold text-emerald-200 bg-emerald-500/30 border border-emerald-400 rounded-lg shadow transition-all cursor-pointer flex items-center gap-1"; if (modeDirectBtn) modeDirectBtn.className = "px-3 py-1.5 text-xs font-medium text-slate-400 bg-slate-900/60 border border-slate-800 rounded-lg hover:text-white transition-all cursor-pointer flex items-center gap-1"; } else if (currentMode === 'direct') { if (iframe) iframe.src = targetUrl; if (statusBadge) statusBadge.innerHTML = '<span class="inline-block w-2 h-2 rounded-full bg-sky-400 animate-pulse"></span> Mode: Direct Stream'; if (modeDirectBtn) modeDirectBtn.className = "px-3 py-1.5 text-xs font-bold text-sky-200 bg-sky-500/30 border border-sky-400 rounded-lg shadow transition-all cursor-pointer flex items-center gap-1"; if (modeProxyBtn) modeProxyBtn.className = "px-3 py-1.5 text-xs font-medium text-slate-400 bg-slate-900/60 border border-slate-800 rounded-lg hover:text-white transition-all cursor-pointer flex items-center gap-1"; } }
function refreshLinkcheckIframe() { const iframe = document.getElementById('glseriesIframe'); if (iframe) { const src = iframe.src; iframe.src = 'about:blank'; setTimeout(() => { iframe.src = src; }, 50); } }
function testLinkcheckStatus() { const input = document.getElementById('linkcheckUrlInput'); const pingResult = document.getElementById('linkcheckPingResult'); let targetUrl = (input ? input.value.trim() : '') || 'https://find.xenorio.xyz/'; if (!/^https?:\/\//i.test(targetUrl)) targetUrl = 'https://' + targetUrl; if (input) input.value = targetUrl;
if (pingResult) pingResult.innerHTML = '<span class="text-sky-400 animate-pulse">Testing ping &amp; status...</span>'; const start = Date.now(); fetch('./api/proxy?url=' + encodeURIComponent(targetUrl), { method: 'HEAD' }) .then(res => { const elapsed = Date.now() - start; if (pingResult) { if (res.ok || res.status < 400) { pingResult.innerHTML = `<span class="text-emerald-400 font-bold">✔ ${res.status || 200} OK</span> <span class="text-slate-400">(${elapsed}ms)</span>`; } else { pingResult.innerHTML = `<span class="text-amber-400 font-bold">⚠ Status ${res.status}</span> <span class="text-slate-400">(${elapsed}ms)</span>`; } } }) .catch(() => { if (pingResult) pingResult.innerHTML = `<span class="text-red-400 font-bold">✖ Host unreachable</span>`; }); }
function openUrlInAboutBlank(url) { const target = url || 'https://find.xenorio.xyz/'; const win = window.open('about:blank', '_blank'); if (!win) { alert("Popup blocked! Please allow popups for this site to open in about:blank."); return; } win.document.title = 'Google Classroom'; const doc = win.document; doc.open(); doc.write(`<html><head><meta charset="utf-8" /><title>Google Classroom</title></head><body><iframe src="${target}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; gamepad; microphone; camera; display-capture" allowfullscreen="allowfullscreen"></iframe></body></html>`); doc.close(); }
// Restore saved tab cloaking on startup (function initTabCloak() { const savedTitle = localStorage.getItem('frost_tab_title'); const savedFavicon = localStorage.getItem('frost_tab_favicon'); if (savedTitle) { document.title = savedTitle; } if (savedFavicon) { let link = document.querySelector("link[rel*='icon']"); if (!link) { link = document.createElement('link'); link.rel = 'shortcut icon'; document.getElementsByTagName('head')[0].appendChild(link); } link.href = savedFavicon; } })();
