// Typewriter animation loop for the tagline words: Experience -> Bypass -> Enjoy -> Be Free -> repeat const typewriterWords = ["Experience", "Bypass", "Enjoy", "Be Free"]; const bypassFonts = [ 'italic 1em "Instrument Serif", serif', 'normal 1em "Instrument Serif", serif', '500 0.85em "JetBrains Mono", monospace', '600 0.9em "Plus Jakarta Sans", sans-serif', 'italic 1em Georgia, "Times New Roman", serif', ]; let lastBypassFontIdx = -1; function randomizeBypassFont(el) { let idx; do { idx = Math.floor(Math.random() * bypassFonts.length); } while (bypassFonts.length > 1 &amp;&amp; idx === lastBypassFontIdx); lastBypassFontIdx = idx; el.style.font = bypassFonts[idx]; el.style.color = ''; } let twWordIdx = 0; let twCharIdx = typewriterWords[0].length; let twIsDeleting = true;
function runTypewriter() { const twEl = document.getElementById('typewriterWord'); if (!twEl) { setTimeout(runTypewriter, 500); return; }
const currentWord = typewriterWords[twWordIdx];
if (twIsDeleting) { twCharIdx--; twEl.innerText = currentWord.substring(0, Math.max(0, twCharIdx)); } else { if (twCharIdx === 0 &amp;&amp; currentWord === "Bypass") { randomizeBypassFont(twEl); } twCharIdx++; twEl.innerText = currentWord.substring(0, Math.min(currentWord.length, twCharIdx)); }
let speed = twIsDeleting ? 60 : 120;
if (!twIsDeleting &amp;&amp; twCharIdx >= currentWord.length) { twCharIdx = currentWord.length; speed = 2500; twIsDeleting = true; } else if (twIsDeleting &amp;&amp; twCharIdx <= 0) { twCharIdx = 0; twIsDeleting = false; twWordIdx = (twWordIdx + 1) % typewriterWords.length; speed = 300; }
setTimeout(runTypewriter, speed); }
(function initBypassFont(){ const el = document.getElementById('typewriterWord'); if (el) randomizeBypassFont(el); })(); setTimeout(runTypewriter, 2500);
// Proxy Engine function setProxyEngine(engine) { localStorage.setItem('proxySearchEngine', engine); updateProxyEngineUI(engine); } function updateProxyEngineUI(engine) { document.querySelectorAll('.engine-btn').forEach(btn => { if (btn.dataset.engine === engine) { btn.classList.add('bg-sky-600', 'text-white', 'border-sky-500'); btn.classList.remove('bg-slate-800', 'text-slate-300', 'border-slate-700'); } else { btn.classList.remove('bg-sky-600', 'text-white', 'border-sky-500'); btn.classList.add('bg-slate-800', 'text-slate-300', 'border-slate-700'); } }); }
// Background Changer function setSiteBackground(type) { let bgValue = ''; if (type === 'custom') { const url = prompt("Enter image URL:"); if (!url) return; document.body.style.background = `url('${url}') no-repeat center center fixed`; document.body.style.backgroundSize = 'cover'; bgValue = `url('${url}')`; localStorage.setItem('siteBg', bgValue); localStorage.setItem('siteBgType', 'custom'); } else { document.body.style.backgroundImage = 'none'; if (type === 'midnight') { document.body.style.background = '#0b1120'; bgValue = '#0b1120'; } else if (type === 'purple') { document.body.style.background = '#1a1025'; bgValue = '#1a1025'; } else if (type === 'black') { document.body.style.background = '#000000'; bgValue = '#000000'; } else { document.body.style.background = '#050914'; bgValue = '#050914'; } localStorage.setItem('siteBg', bgValue); localStorage.setItem('siteBgType', type); } updateBgUI(type === 'custom' ? 'custom' : type); } function updateBgUI(type) { document.querySelectorAll('.bg-btn').forEach(btn => { if (btn.dataset.bg === type) { btn.classList.add('ring-2', 'ring-sky-500', 'ring-offset-2', 'ring-offset-slate-900'); } else { btn.classList.remove('ring-2', 'ring-sky-500', 'ring-offset-2', 'ring-offset-slate-900'); } }); } // Initialization for settings (function() { const engine = localStorage.getItem('proxySearchEngine') || 'bing'; updateProxyEngineUI(engine);
const bg = localStorage.getItem('siteBg'); const bgType = localStorage.getItem('siteBgType') || 'default'; updateBgUI(bgType); if (bg) { if (bg.startsWith('url(')) { document.body.style.background = bg + ' no-repeat center center fixed'; document.body.style.backgroundSize = 'cover'; } else { document.body.style.background = bg; } } })();
